import urllib.request
import json
import numpy as np

url = "http://mcp-server:8000/mcp"
session_id = "bc7cbe8f4c6e4308a314cf1ad8f1c23c"

# Get more simulation data for better estimates - 200 draws each
segments = ["S1", "S2", "S3", "S4", "S5", "S6"]
checks = ["bureau", "income", "bank"]

all_scores = {}

for segment in segments:
    all_scores[segment] = {}
    for check in checks:
        payload = {
            "jsonrpc": "2.0",
            "id": hash(f"{segment}{check}") % 10000,
            "method": "tools/call",
            "params": {
                "name": "simulate",
                "arguments": {
                    "segment": segment,
                    "check": check,
                    "n": 200
                }
            }
        }

        data = json.dumps(payload).encode('utf-8')
        req = urllib.request.Request(url, data=data, headers={
            'Content-Type': 'application/json',
            'Accept': 'application/json, text/event-stream',
            'Mcp-Session-Id': session_id
        })

        try:
            with urllib.request.urlopen(req, timeout=10) as response:
                for line in response:
                    line = line.decode('utf-8').strip()
                    if line.startswith('data: '):
                        result = json.loads(line[6:])
                        scores = result['result']['structuredContent']['scores']
                        all_scores[segment][check] = scores
                        print(f"{segment} {check}: mean={np.mean(scores):.1f}, std={np.std(scores):.1f}, n={len(scores)}")
        except Exception as e:
            print(f"Error {segment} {check}: {e}")

# Save to file for analysis
with open('/tmp/sim_scores.json', 'w') as f:
    json.dump(all_scores, f)

print("Done collecting simulation data")
