def compute_posterior(prior, checks_history):
    """Compute posterior given prior and check results"""
    posterior = prior.copy()
    for check, band in checks_history:
        # P(band | segment, check)
        likelihood = {seg: band_probs[seg][check][band] for seg in prior}
        # Bayes update
        for seg in posterior:
            posterior[seg] *= likelihood[seg]
        # Normalize
        total = sum(posterior.values())
        for seg in posterior:
            posterior[seg] /= total
    return posterior

