        if p_band == 0:
            continue
        # Posterior if this band observed
        post = {}
        for seg in prior:
            post[seg] = band_probs[seg][check][band] * prior[seg] / p_band
        ev_post = expected_value(post)
        total_ev += p_band * max(0, ev_post)  # We can always decline
    return total_ev

# Test on applicant 1
print("Applicant 1 prior:", priors[0])
print("EV(approve) without checks:", expected_value(priors[0]))

for check in ["bureau", "income", "bank"]:
    voi = value_of_info(priors[0], check)
    print(f"  VOI({check}) = {voi:.2f}, net VOI = {voi - 20:.2f}")

