    "S4": {"bureau": [0.520, 0.380, 0.060, 0.020, 0.020, 0.001], "income": [0.320, 0.220, 0.240, 0.080, 0.020, 0.120], "bank": [0.140, 0.340, 0.240, 0.120, 0.020, 0.140]},
    "S5": {"bureau": [0.380, 0.420, 0.140, 0.040, 0.001, 0.019], "income": [0.160, 0.360, 0.220, 0.160, 0.020, 0.080], "bank": [0.260, 0.440, 0.160, 0.020, 0.020, 0.100]},
